// Generated by esquadro: do not edit. Saved filters of a list: its search,
// filters and order under a name ("Active and expensive"), applied again
// in one click. Kept in this browser.
import { Check, Star, Trash2 } from "../icons.gen.ts"
import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { cn } from "@/lib/utils"
import { base } from "../config.ts"
import { t } from "./i18n.ts"
import type { ResourceMeta } from "./meta.ts"
import { toast } from "./toast.tsx"

export type ViewSearch = Record<string, string | number | undefined>

export interface View {
  name: string
  search: ViewSearch
}

/** A list's state as a view keeps it: without its page. */
export function viewOf(search: ViewSearch): ViewSearch {
  const out: ViewSearch = {}
  for (const k of Object.keys(search).sort()) {
    if (k !== "page" && k !== "cursor" && search[k] !== undefined && search[k] !== "") out[k] = search[k]
  }
  return out
}

const same = (a: ViewSearch, b: ViewSearch) => JSON.stringify(viewOf(a)) === JSON.stringify(viewOf(b))

function storageKey(meta: ResourceMeta) {
  return `esquadro:${base}:${meta.name}:views`
}

function load(meta: ResourceMeta): View[] {
  try {
    return JSON.parse(localStorage.getItem(storageKey(meta)) ?? "[]") as View[]
  } catch {
    return []
  }
}

/** The views saved for a resource's list, and how to save and remove them. */
export function useViews(meta: ResourceMeta) {
  const [views, setViews] = useState<View[]>(() => load(meta))
  const store = (next: View[]) => {
    setViews(next)
    try {
      localStorage.setItem(storageKey(meta), JSON.stringify(next))
    } catch {
      // Storage refused (a private window): the views last the visit.
    }
  }
  return {
    views,
    save: (name: string, search: ViewSearch) => store([...views.filter((v) => v.name !== name), { name, search: viewOf(search) }]),
    remove: (name: string) => store(views.filter((v) => v.name !== name)),
  }
}

/**
 * The saved filters of a list, shown only when there is one: each applies
 * its search, filters and order; the one applied now is checked.
 */
export function SavedFiltersMenu({
  views,
  search,
  onApply,
  onRemove,
}: {
  views: View[]
  search: ViewSearch
  onApply: (search: ViewSearch) => void
  onRemove: (name: string) => void
}) {
  if (views.length === 0) return null
  const current = views.find((v) => same(v.search, search))
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" className={cn(current && "border-primary text-primary")}>
          <Star className={cn(current && "fill-current")} />
          <span className="max-w-40 truncate">{current ? current.name : t("savedFilters")}</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-64">
        <DropdownMenuLabel className="text-xs font-normal text-muted-foreground">{t("savedFilters")}</DropdownMenuLabel>
        {views.map((v) => (
          <DropdownMenuItem key={v.name} onClick={() => onApply(v.search)} className="group/view font-semibold">
            {current?.name === v.name ? <Check className="text-primary" /> : <span className="size-4" />}
            <span className="flex-1 truncate">{v.name}</span>
            <Button
              variant="ghost"
              size="icon-xs"
              className="opacity-0 group-hover/view:opacity-100 focus-visible:opacity-100"
              aria-label={`${t("delete")} ${v.name}`}
              onClick={(e) => {
                e.stopPropagation()
                onRemove(v.name)
                toast(t("filterDeleted"))
              }}
            >
              <Trash2 />
            </Button>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

/**
 * Save filter, beside the filters set: names what the list shows now. Not
 * shown when it is already saved, or when nothing is filtered.
 */
export function SaveFilterButton({ views, search, onSave }: { views: View[]; search: ViewSearch; onSave: (name: string) => void }) {
  const [naming, setNaming] = useState(false)
  const [name, setName] = useState("")
  if (Object.keys(viewOf(search)).length === 0 || views.some((v) => same(v.search, search))) return null
  return (
    <>
      <Button
        variant="ghost"
        size="sm"
        className="text-primary hover:text-primary"
        onClick={() => {
          setName("")
          setNaming(true)
        }}
      >
        <Star /> {t("saveFilter")}
      </Button>
      <Dialog open={naming} onOpenChange={setNaming}>
        <DialogContent className="sm:max-w-md">
          <form
            className="flex flex-col gap-5"
            onSubmit={(e) => {
              e.preventDefault()
              if (!name.trim()) return
              onSave(name.trim())
              setNaming(false)
              toast(t("filterSaved"))
            }}
          >
            <DialogHeader>
              <DialogTitle>{t("saveFilter")}</DialogTitle>
              <DialogDescription>{t("saveFilterHint")}</DialogDescription>
            </DialogHeader>
            <div className="flex flex-col gap-2">
              <Label htmlFor="saved-filter-name">{t("filterName")}</Label>
              <Input id="saved-filter-name" autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder={t("filterNameExample")} />
            </div>
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => setNaming(false)}>
                {t("cancel")}
              </Button>
              <Button type="submit" disabled={!name.trim()}>
                {t("save")}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </>
  )
}
